import { Draggable } from "@hello-pangea/dnd";
import { useRedirect, RecordContextProvider } from "ra-core";
import { ReferenceField } from "@/components/admin/reference-field";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

import { CompanyAvatar } from "../companies/CompanyAvatar";
import {
  calculateMilestoneDate,
  getMilestoneStatus,
} from "../dashboard/escrowTimelineUtils";
import type { Deal } from "../types";

const getMilestoneHealth = (deal: Deal) => {
  const milestones = deal.milestones?.filter((m) => m.enabled) ?? [];
  if (milestones.length === 0) return null;

  let overdueCount = 0;
  let completedCount = 0;
  for (const milestone of milestones) {
    const date = calculateMilestoneDate(
      milestone,
      deal.acceptance_date,
      deal.expected_closing_date,
    );
    const status = getMilestoneStatus(milestone, date);
    if (status === "overdue") overdueCount++;
    if (status === "completed") completedCount++;
  }

  return {
    completed: completedCount,
    total: milestones.length,
    hasOverdue: overdueCount > 0,
  };
};

const representationLabel: Record<string, string> = {
  buyer: "Buyer",
  seller: "Seller",
  both: "Both",
};

export const DealCard = ({ deal, index }: { deal: Deal; index: number }) => {
  if (!deal) return null;

  return (
    <Draggable draggableId={String(deal.id)} index={index}>
      {(provided, snapshot) => (
        <DealCardContent provided={provided} snapshot={snapshot} deal={deal} />
      )}
    </Draggable>
  );
};

export const DealCardContent = ({
  provided,
  snapshot,
  deal,
}: {
  provided?: any;
  snapshot?: any;
  deal: Deal;
}) => {
  const redirect = useRedirect();
  const health = getMilestoneHealth(deal);
  const handleClick = () => {
    redirect(`/deals/${deal.id}/show`, undefined, undefined, undefined, {
      _scrollToTop: false,
    });
  };

  return (
    <div
      className="cursor-pointer"
      {...provided?.draggableProps}
      {...provided?.dragHandleProps}
      ref={provided?.innerRef}
      onClick={handleClick}
    >
      <RecordContextProvider value={deal}>
        <Card
          className={`py-3 transition-all duration-200 ${
            snapshot?.isDragging
              ? "opacity-90 transform rotate-1 shadow-lg"
              : "shadow-sm hover:shadow-md"
          }`}
        >
          <CardContent className="px-3 flex">
            <ReferenceField
              source="company_id"
              reference="companies"
              link={false}
            >
              <CompanyAvatar width={20} height={20} />
            </ReferenceField>
            <div className="ml-3 flex-1 min-w-0">
              <p
                className="text-sm font-medium mb-1 truncate"
                title={deal.name}
              >
                {deal.name}
              </p>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-xs text-muted-foreground">
                  {deal.amount.toLocaleString("en-US", {
                    notation: "compact",
                    style: "currency",
                    currency: "USD",
                    currencyDisplay: "narrowSymbol",
                    minimumSignificantDigits: 3,
                  })}
                </span>
                {deal.representation && (
                  <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                    {representationLabel[deal.representation] ||
                      deal.representation}
                  </Badge>
                )}
                {health && (
                  <span
                    className={`ml-auto text-xs font-medium ${
                      health.hasOverdue ? "text-destructive" : "text-green-500"
                    }`}
                  >
                    {health.completed}/{health.total}
                  </span>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      </RecordContextProvider>
    </div>
  );
};
