const ArchivedTitle = () => (
  <div className="bg-orange-500 px-6 py-4">
    <h3 className="text-lg font-bold text-white">Archived Escrow</h3>
  </div>
);

const LinkedListingDisplay = ({ listingKey }: { listingKey: string }) => {
  const { data: listing, isPending } = useGetOne<
    OfficeListing & { id: string }
  >("listings", { id: listingKey }, { enabled: !!listingKey });

  if (isPending) {
    return (
      <div className="m-4">
        <span className="text-xs text-muted-foreground tracking-wide">
          Linked Listing
        </span>
        <p className="text-sm text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (!listing) {
    return (
      <div className="m-4">
        <span className="text-xs text-muted-foreground tracking-wide">
          Linked Listing
        </span>
        <p className="text-sm text-muted-foreground italic">
          Listing no longer available
        </p>
      </div>
    );
  }

  return (
    <div className="m-4">
      <span className="text-xs text-muted-foreground tracking-wide">
        Linked Listing
      </span>
      <div className="flex items-center gap-1.5 mt-1">
        <Home className="w-4 h-4 text-muted-foreground" />
        <a
          href={`${LISTING_PREVIEW_BASE_URL}/${listing.listing_key}`}
          target="_blank"
          rel="noopener noreferrer"
          className="text-sm underline hover:no-underline text-primary"
        >
          {listing.unparsed_address}
        </a>
        <ExternalLink className="w-3 h-3 text-muted-foreground" />
        <span className="text-xs text-muted-foreground ml-2">
          {new Intl.NumberFormat("en-US", {
            style: "currency",
            currency: "USD",
            maximumFractionDigits: 0,
          }).format(listing.list_price)}
        </span>
        <Badge variant="outline" className="text-[10px] px-1.5 py-0 ml-1">
          {listing.standard_status}
        </Badge>
      </div>
    </div>
  );
};

const ArchiveButton = ({ record }: { record: Deal }) => {
  const [update] = useUpdate();
  const redirect = useRedirect();
  const notify = useNotify();
  const refresh = useRefresh();
  const handleClick = () => {
    update(
      "deals",
      {
        id: record.id,
        data: { archived_at: new Date().toISOString() },
        previousData: record,
      },
      {
        onSuccess: () => {
          redirect("list", "deals");
          notify("Escrow archived", { type: "info", undoable: false });
          refresh();
        },
        onError: () => {
          notify("Error: escrow not archived", { type: "error" });
        },
      },
    );
  };

  return (
    <Button
      onClick={handleClick}
      size="sm"
      variant="outline"
      className="flex items-center gap-2 h-9"
    >
      <Archive className="w-4 h-4" />
      Archive
    </Button>
  );
};

const UnarchiveButton = ({ record }: { record: Deal }) => {
  const dataProvider = useDataProvider();
  const redirect = useRedirect();
  const notify = useNotify();
  const refresh = useRefresh();

  const { mutate } = useMutation({
    mutationFn: () => dataProvider.unarchiveDeal(record),
    onSuccess: () => {
      redirect("list", "deals");
      notify("Escrow unarchived", {
        type: "info",
        undoable: false,
      });
      refresh();
    },
    onError: () => {
      notify("Error: escrow not unarchived", { type: "error" });
    },
  });

  const handleClick = () => {
    mutate();
  };

  return (
    <Button
      onClick={handleClick}
      size="sm"
      variant="outline"
      className="flex items-center gap-2 h-9"
    >
      <ArchiveRestore className="w-4 h-4" />
      Send back to the board
    </Button>
  );
};

const MilestonesDisplay = ({
  milestones,
  acceptanceDate,
  closingDate,
}: {
  milestones: EscrowMilestone[];
  acceptanceDate?: string;
  closingDate?: string;
}) => {
  const record = useRecordContext<Deal>();
  const [update] = useUpdate();

  // Filter enabled milestones and sort chronologically by calculated date
  const enabledMilestones = useMemo(() => {
    const enabled = milestones.filter((m) => m.enabled);
    return enabled.sort((a, b) => {
      const dateA = calculateMilestoneDate(a, acceptanceDate, closingDate);
      const dateB = calculateMilestoneDate(b, acceptanceDate, closingDate);
      // Milestones without dates go to the end
      if (!dateA && !dateB) return 0;
      if (!dateA) return 1;
      if (!dateB) return -1;
      return dateA.getTime() - dateB.getTime();
    });
  }, [milestones, acceptanceDate, closingDate]);

  // Toggle completed_at for a milestone — deep-clone the full JSONB array,
  // flip the target, and send the whole array back via useUpdate.
  // Pattern mirrors MilestoneRow.tsx:85-89 for the completed_at toggle
  // and ArchiveButton for previousData rollback.
  const handleToggleCompleted = useCallback(
    (milestoneId: string) => {
      if (!record) return;

      const updatedMilestones: EscrowMilestone[] = record.milestones.map(
        (m) => {
          if (m.id !== milestoneId) return { ...m };
          return {
            ...m,
            completed_at: m.completed_at ? undefined : new Date().toISOString(),
          };
        },
      );

      update(
        "deals",
        {
          id: record.id,
          data: { milestones: updatedMilestones },
          previousData: record,
        },
        {
          // No notification — the green checkmark appearing is sufficient feedback
          mutationMode: "optimistic",
        },
      );
    },
    [record, update],
  );

  const completedCount = enabledMilestones.filter((m) => m.completed_at).length;

  if (enabledMilestones.length === 0) return null;

  return (
    <div className="m-4">
      <Separator className="mb-4" />
      <div className="flex items-center gap-2 mb-3">
        <span className="text-xs text-muted-foreground tracking-wide">
          Milestones
        </span>
        <Badge variant="secondary" className="text-xs">
          {completedCount}/{enabledMilestones.length}
        </Badge>
      </div>
      <div className="grid gap-2">
        {enabledMilestones.map((milestone) => {
          const date = calculateMilestoneDate(
            milestone,
            acceptanceDate,
            closingDate,
          );
          const isPast = date && date < new Date() && !milestone.completed_at;
          const isCompleted = !!milestone.completed_at;

          return (
            <div key={milestone.id} className="flex items-center gap-3 text-sm">
              <button
                type="button"
                onClick={() => handleToggleCompleted(milestone.id)}
                className="shrink-0 cursor-pointer hover:opacity-70 transition-opacity"
                aria-label={`${isCompleted ? "Uncomplete" : "Complete"} ${milestone.name}`}
              >
                {isCompleted ? (
                  <CheckCircle2 className="w-4 h-4 text-green-500" />
                ) : isPast ? (
                  <AlertCircle className="w-4 h-4 text-red-500" />
                ) : (
                  <Circle className="w-4 h-4 text-muted-foreground" />
                )}
              </button>
              <span
                className={`flex-1 ${
                  isCompleted ? "line-through text-muted-foreground" : ""
                } ${isPast ? "text-red-600 font-medium" : ""}`}
              >
                {milestone.name}
              </span>
              {milestone.rpa_reference && (
                <span className="text-xs text-muted-foreground">
                  {milestone.rpa_reference}
                </span>
              )}
              {date && (
                <span
                  className={`text-sm ${
                    isPast
                      ? "text-red-600 font-medium"
                      : "text-muted-foreground"
                  }`}
                >
                  {format(date, "MMM d")}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
