import { useEffect, useMemo } from "react";
import { useQueryClient } from "@tanstack/react-query";
import {
  Form,
  useDataProvider,
  useGetIdentity,
  useListContext,
  useRedirect,
  type GetListResult,
} from "ra-core";
import { useWatch } from "react-hook-form";
import { Create } from "@/components/admin/create";
import { SaveButton } from "@/components/admin/form";
import { FormToolbar } from "@/components/admin/simple-form";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";

import type { Deal, EscrowMilestone } from "../types";
import { DealInputs } from "./DealInputs";
import { defaultEscrowMilestones } from "../root/defaultConfiguration";

// Generate initial milestones with unique IDs
const getInitialMilestones = (): EscrowMilestone[] =>
  defaultEscrowMilestones.map((m) => ({
    ...m,
    id: crypto.randomUUID(),
  }));

// --- Draft persistence helpers ---
const DRAFT_KEY = "escrow-create-draft";

const getDraft = (): Record<string, unknown> | null => {
  try {
    const raw = sessionStorage.getItem(DRAFT_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};

const clearDraft = () => sessionStorage.removeItem(DRAFT_KEY);

/** Render inside <Form> to auto-save values to sessionStorage. */
const DraftFormPersistence = () => {
  const values = useWatch();
  useEffect(() => {
    const id = setTimeout(() => {
      try {
        sessionStorage.setItem(DRAFT_KEY, JSON.stringify(values));
      } catch {
        /* ignore storage errors */
      }
    }, 500);
    return () => clearTimeout(id);
  }, [values]);
  return null;
};

export const DealCreate = ({ open }: { open: boolean }) => {
  const redirect = useRedirect();
  const dataProvider = useDataProvider();
  const { data: allDeals } = useListContext<Deal>();

  const handleClose = () => {
    clearDraft();
    redirect("/deals");
  };

  const queryClient = useQueryClient();

  const onSuccess = async (deal: Deal) => {
    clearDraft();
    if (!allDeals) {
      redirect("/deals");
      return;
    }
    // increase the index of all deals in the same stage as the new deal
    // first, get the list of deals in the same stage
    const deals = allDeals.filter(
      (d: Deal) => d.stage === deal.stage && d.id !== deal.id,
    );
    // update the actual deals in the database
    await Promise.all(
      deals.map(async (oldDeal) =>
        dataProvider.update("deals", {
          id: oldDeal.id,
          data: { index: oldDeal.index + 1 },
          previousData: oldDeal,
        }),
      ),
    );
    // refresh the list of deals in the cache as we used dataProvider.update(),
    // which does not update the cache
    const dealsById = deals.reduce(
      (acc, d) => ({
        ...acc,
        [d.id]: { ...d, index: d.index + 1 },
      }),
      {} as { [key: string]: Deal },
    );
    const now = Date.now();
    queryClient.setQueriesData<GetListResult | undefined>(
      { queryKey: ["deals", "getList"] },
      (res) => {
        if (!res) return res;
        return {
          ...res,
          data: res.data.map((d: Deal) => dealsById[d.id] || d),
        };
      },
      { updatedAt: now },
    );
    redirect("/deals");
  };

  const { identity } = useGetIdentity();

  // Memoize milestones so new UUIDs aren't generated on every re-render,
  // which would cause ra-core's useAugmentedForm to reset the form.
  const initialMilestones = useMemo(() => getInitialMilestones(), []);

  const draft = getDraft();
  const defaultValues = draft ?? {
    sales_id: identity?.id,
    contact_ids: [],
    index: 0,
    milestones: initialMilestones,
  };

  return (
    <Dialog open={open} onOpenChange={() => {}}>
      <DialogContent
        className="lg:max-w-4xl overflow-y-auto max-h-9/10 top-1/20 translate-y-0"
        onCloseClick={handleClose}
      >
        <DialogTitle>New Escrow</DialogTitle>
        <Create resource="deals" mutationOptions={{ onSuccess }}>
          <Form defaultValues={defaultValues}>
            <DraftFormPersistence />
            <DealInputs />
            <FormToolbar>
              <SaveButton />
            </FormToolbar>
          </Form>
        </Create>
      </DialogContent>
    </Dialog>
  );
};
