import { useState, useEffect } from "react";
import { useFormContext, useWatch } from "react-hook-form";
import { NumberInput } from "@/components/admin/number-input";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";

interface CommissionInputProps {
  side: "buyer" | "seller";
  label: string;
}

export const CommissionInput = ({ side, label }: CommissionInputProps) => {
  const pctSource = `${side}_commission_pct`;
  const amtSource = `${side}_commission_amt`;

  const { setValue } = useFormContext();
  const amtValue = useWatch({ name: amtSource });

  // Show amount field if it has a value
  const [showAmount, setShowAmount] = useState(false);

  useEffect(() => {
    if (amtValue != null && amtValue !== "" && amtValue !== 0) {
      setShowAmount(true);
    }
  }, [amtValue]);

  const handleToggle = (checked: boolean) => {
    setShowAmount(checked);
    if (!checked) {
      // Clear amount when switching back to percentage mode
      setValue(amtSource, null);
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between">
        <Label className="text-sm font-medium">{label}</Label>
        <div className="flex items-center gap-2">
          <Switch
            id={`${side}-commission-toggle`}
            checked={showAmount}
            onCheckedChange={handleToggle}
          />
          <Label
            htmlFor={`${side}-commission-toggle`}
            className="text-xs text-muted-foreground"
          >
            Fixed
          </Label>
        </div>
      </div>

      {showAmount ? (
        <NumberInput
          source={amtSource}
          label="Amount ($)"
          helperText={false}
          min={0}
          step={1}
        />
      ) : (
        <NumberInput
          source={pctSource}
          label="Amount (%)"
          helperText={false}
          min={0}
          max={100}
          step={0.1}
        />
      )}
    </div>
  );
};
